CHILD_TURN_ROUTE_ID_PATTERN = new RegExp(`^${CHILD_TURN_ROUTE_ID_PREFIX}:${CLOUD_OR_BARE_AGENT_ID_SOURCE}:${CLOUD_OR_BARE_AGENT_ID_SOURCE}$`, "i");
CHILD_INBOX_RUN_ID_PATTERN = /^[A-Za-z0-9_-]+$/;
